CREATE TABLE IF NOT EXISTS richo_security_identities(id uuid PRIMARY KEY,subject text NOT NULL,type text NOT NULL,capabilities jsonb NOT NULL DEFAULT '[]'::jsonb,trust_zone text NOT NULL DEFAULT 'internal',status text NOT NULL DEFAULT 'active',correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_security_events_l2(id uuid PRIMARY KEY,type text NOT NULL,actor text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,previous_hash text NOT NULL DEFAULT '',hash text NOT NULL UNIQUE,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_secret_rotation_status(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),secret_ref text NOT NULL UNIQUE,last_rotated_at timestamptz NOT NULL,max_age_days integer NOT NULL DEFAULT 30,status text NOT NULL DEFAULT 'current',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_security_posture_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),score integer NOT NULL,status text NOT NULL,metrics jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_security_isolations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject text NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'isolated',approved_release_by text,created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz);
CREATE INDEX IF NOT EXISTS richo_security_identity_subject_idx ON richo_security_identities(subject,status);
